// Slack posts a form with one field, payload (JSON).
const raw = $json.body?.payload ?? $json.payload;
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;
const action = (p?.actions ?? []).find((a) => a.action_id === 'landbright_approve' || a.action_id === 'landbright_deny');
if (!action) return { skip: true };
const [requestId, ticket] = String(action.value).split('|');
return { skip: false, requestId, ticket, outcome: action.action_id === 'landbright_approve' ? 'approve' : 'deny', slackUser: p.user?.id ?? '', team: p.team?.id ?? '', responseUrl: p.response_url ?? '' };
